// Generates the Apps Script files that must stay identical to the browser app:
//   backend/src/Shared.gs  – engine, modules, labor, auditor, revisions and state blocks of estimator.html
//   backend/src/Index.html – the app page served by doGet()
// Usage: node scripts/build-backend.mjs [--check]   (--check fails if the generated files are out of date)
import fs from 'node:fs';
import path from 'node:path';
import {ROOT, APP_HTML, engineSource, sha256} from '../tests/lib/engine.mjs';

const BLOCKS = ['engine', 'modules', 'labor', 'auditor', 'revisions', 'state'];
const html = fs.readFileSync(APP_HTML, 'utf8');
const shared = `// GENERATED by scripts/build-backend.mjs from estimator.html – do not edit by hand.
// Source sha256: ${sha256(html)}
// The server runs exactly the same calculation, migration and audit code as the browser.
${BLOCKS.map(b => `\n// ===== <script id="${b}"> =====\n` + engineSource(APP_HTML, b)).join('\n')}
`;
const out = {'backend/src/Shared.gs': shared, 'backend/src/Index.html': html};
const check = process.argv.includes('--check');
let stale = [];
for (const [rel, text] of Object.entries(out)) {
  const file = path.join(ROOT, rel);
  const cur = fs.existsSync(file) ? fs.readFileSync(file, 'utf8') : null;
  if (cur !== text) { stale.push(rel); if (!check) fs.writeFileSync(file, text); }
}
if (check) { console.log(stale.length ? 'OUT OF DATE: ' + stale.join(', ') : 'Backend build is up to date'); process.exit(stale.length ? 1 : 0); }
console.log(stale.length ? 'Wrote ' + stale.join(', ') : 'Backend build already up to date');
